#include <stdio.h>
#include <stdlib.h>

#define MOD 998244353

int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int N;
    scanf("%d", &N);
    int size = 2 * N;
    int h[100000];
    for (int i = 0; i < size; i++) {
        scanf("%d", &h[i]);
    }
    qsort(h, size, sizeof(int), cmp);

    long long ans = 1;
    int unmatched = 0;
    int i = 0;
    while (i < size) {
        int j = i;
        while (j < size && h[j] == h[i]) j++;
        int cnt = j - i;
        if (cnt > unmatched) {
            printf("0\n");
            return 0;
        }
        // For each of these cnt people, we can match them with any of the unmatched
        for (int k = 0; k < cnt; k++) {
            ans = (ans * (unmatched - k)) % MOD;
        }
        unmatched -= cnt;
        // Now these cnt people become unmatched for future taller people
        unmatched += cnt;
        i = j;
    }
    // At the end, unmatched should be 0
    printf("%lld\n", ans);
    return 0;
}

