int main(){
    int N; scanf("%d",&N);
    for(int i=0;i<2*N;i++){int h;scanf("%d",&h);cnt[h]++;}
    poly[0]=1; int deg=0;
    long long fact[100002]; fact[0]=1;
    for(int i=1;i<=100001;i++) fact[i]=fact[i-1]*i%MOD;
    long long inv2=499122177LL;
    for(int v=1;v<=100000;v++){
        int c=cnt[v]; if(c<2) continue;
        int maxj=c/2;
        // multiply poly by sum_{j=0}^{maxj} C(c,2j)*(2j-1)!!*x^j
        // (2j-1)!! = fact[2j]/(2^j*fact[j])
        long long pw2=1; // 2^j
        long long gpoly[maxj+1];
        long long pw2inv=1;
        for(int j=0;j<=maxj;j++){
            // C(c,2j)*(2j-1)!! = fact[c]/(fact[c-2j]*fact[2j]) * fact[2j]/(2^j*fact[j]) = fact[c]/((fact[c-2j]*pw2*fact[j]))
            gpoly[j]=fact[c]%MOD;
            // divide by fact[c-2j]*2^j*fact[j]
            // need modular inverse
            long long denom=fact[c-2*j]%MOD*pw2inv%MOD*fact[j]%MOD;
            // compute inverse of denom
            long long base=denom,exp=MOD-2,res=1;
            while(exp>0){if(exp&1)res=res*base%MOD;base=base*base%MOD;exp>>=1;}
            gpoly[j]=gpoly[j]*res%MOD;
            pw2inv=pw2inv*(MOD+1)/2%MOD; // *inv2
            pw2inv=pw2inv*inv2%MOD;
        }
        // convolve
        int newdeg=deg+maxj;
        for(int i=newdeg;i>=0;i--) tmp[i]=0;
        for(int i=deg;i>=0;i--) if(poly[i]) for(int j=maxj;j>=0;j--) tmp[i+j]=(tmp[i+j]+poly[i]*gpoly[j])%MOD;
        for(int i=0;i<=newdeg;i++) poly[i]=tmp[i];
        deg=newdeg;
    }
    // double_fact[k] = (2k-1)!! = fact[2k]/(2^k*k!)
    long long ans=0;
    long long pw2inv=1;
    for(int k=0;k<=N;k++){
        int rem=N-k;
        // (2rem-1)!! 
        long long df;
        if(rem==0) df=1;
        else {
            long long denom=pw2inv*fact[rem]%MOD;
            long long base=denom,exp=MOD-2,res=1;
            while(exp>0){if(exp&1)res=res*base%MOD;base=base*base%MOD;exp>>=1;}
            df=fact[2*rem]%MOD*res%MOD;
        }
        long long term=poly[k]*df%MOD;
        if(k%2==0) ans=(ans+term)%MOD;
        else ans=(ans-term+MOD)%MOD;
        pw2inv=pw2inv*inv2%MOD;
    }
    printf("%lld\n",ans);
}

#include <stdio.h>
#include <stdlib.h>

#define MOD 998244353LL

static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

long long mod_pow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int M = 2 * N;
    long long *h = (long long *)malloc(sizeof(long long) * M);
    for (int i = 0; i < M; i++) scanf("%lld", &h[i]);

    qsort(h, M, sizeof(long long), cmp_ll);

    /* Count frequencies of each distinct height */
    int *cnt = (int *)malloc(sizeof(int) * M);
    int K = 0;
    for (int i = 0; i < M; ) {
        int j = i + 1;
        while (j < M && h[j] == h[i]) j++;
        cnt[K++] = j - i;
        i = j;
    }

    /* Precompute factorials up to 2N */
    long long *fact = (long long *)malloc(sizeof(long long) * (M + 1));
    fact[0] = 1;
    for (int i = 1; i <= M; i++) fact[i] = fact[i - 1] * i % MOD;

    /*
      Let counts be c1, c2, ..., cK for each height group.
      Number of valid perfect matchings with no equal-height pair is:
        (2N)! / (2^N N!) * [x^N] prod_i (sum_{t=0}^{floor(ci/2)} (-1)^t / (2^t t!) * C(ci, 2t) * (2t)! * x^t)
      This simplifies to:
        (2N)! / (2^N N!) * [x^N] prod_i (sum_t (-1)^t * ci! / ((ci-2t)! 2^t t!) * x^t)

      We compute the coefficient by DP over groups.
    */

    long long inv2 = (MOD + 1) / 2;
    long long *invfact = (long long *)malloc(sizeof(long long) * (M + 1));
    invfact[M] = mod_pow(fact[M], MOD - 2);
    for (int i = M; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    long long *dp = (long long *)calloc(N + 1, sizeof(long long));
    long long *ndp = (long long *)calloc(N + 1, sizeof(long long));
    dp[0] = 1;

    for (int i = 0; i < K; i++) {
        int c = cnt[i];
        for (int j = 0; j <= N; j++) ndp[j] = 0;

        long long coef = 1; /* t = 0 */
        for (int used = 0; used <= N; used++) {
            if (dp[used] == 0) continue;

            long long cur = 1;
            for (int t = 0; t <= c / 2 && used + t <= N; t++) {
                long long add = dp[used] * cur % MOD;
                ndp[used + t] += add;
                if (ndp[used + t] >= MOD) ndp[used + t] -= MOD;

                if (t == c / 2 || used + t == N) break;

                /*
                  cur(t+1) = cur(t) * (-(c-2t)(c-2t-1)/2/(t+1))
                */
                long long a = c - 2LL * t;
                long long b = c - 2LL * t - 1;
                cur = cur * a % MOD;
                cur = cur * b % MOD;
                cur = cur * inv2 % MOD;
                cur = cur * mod_pow(t + 1, MOD - 2) % MOD;
                cur = (MOD - cur) % MOD;
            }
        }

        long long *tmp = dp;
        dp = ndp;
        ndp = tmp;
    }

    long long total_matchings = fact[M];
    total_matchings = total_matchings * mod_pow(mod_pow(2, N), MOD - 2) % MOD;
    total_matchings = total_matchings * mod_pow(fact[N], MOD - 2) % MOD;

    long long ans = total_matchings * dp[N] % MOD;
    printf("%lld\n", ans);

    free(h);
    free(cnt);
    free(fact);
    free(invfact);
    free(dp);
    free(ndp);
    return 0;
}

