const int MOD = 998244353;

long long mod_pow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

int main(){
    int N;
    cin >> N;

    map<int,int> cnt;
    for(int i = 0; i < 2*N; i++){
        int h; cin >> h;
        cnt[h]++;
    }

    // Precompute factorials
    vector<long long> fact(2*N+2), inv_fact(2*N+2);
    fact[0] = 1;
    for(int i = 1; i <= 2*N+1; i++) fact[i] = fact[i-1]*i%MOD;
    inv_fact[2*N+1] = mod_pow(fact[2*N+1], MOD-2, MOD);
    for(int i = 2*N; i >= 0; i--) inv_fact[i] = inv_fact[i+1]*(i+1)%MOD;

    // double factorial (2k-1)!! = fact[2k]/(2^k * fact[k])
    auto double_fact = [&](int k) -> long long {
        if(k < 0) return 0;
        if(k == 0) return 1;
        return fact[2*k] % MOD * inv_fact[k] % MOD * mod_pow(mod_pow(2, k, MOD), MOD-2, MOD) % MOD;
    };

    vector<long long> poly = {1};

    for(auto& [h, c] : cnt){
        vector<long long> g;
        for(int j = 0; j <= c/2; j++){
            long long coef = fact[c] % MOD * inv_fact[2*j] % MOD * inv_fact[c-2*j] % MOD * double_fact(j) % MOD;
            if(j % 2 == 1) coef = (MOD - coef) % MOD;
            g.push_back(coef);
        }
        // multiply poly by g
        vector<long long> np(poly.size() + g.size() - 1, 0);
        for(int i = 0; i < (int)poly.size(); i++)
            for(int j = 0; j < (int)g.size(); j++)
                np[i+j] = (np[i+j] + poly[i]*g[j]) % MOD;
        poly = np;
    }

    long long ans = 0;
    for(int k = 0; k < (int)poly.size(); k++){
        ans = (ans + poly[k] * double_fact(N-k)) % MOD;
    }
    cout << ans << endl;
}

