using namespace std;

static const long long MOD = 998244353;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    int M = 2 * N;

    vector<int> h(M);
    int mx = 0;
    for (int i = 0; i < M; ++i) {
        cin >> h[i];
        mx = max(mx, h[i]);
    }

    vector<int> cnt(mx + 1, 0);
    for (int x : h) cnt[x]++;

    // Precompute factorials up to 2N
    vector<long long> fact(M + 1), invfact(M + 1);
    fact[0] = 1;
    for (int i = 1; i <= M; ++i) fact[i] = fact[i - 1] * i % MOD;
    invfact[M] = modpow(fact[M], MOD - 2);
    for (int i = M; i >= 1; --i) invfact[i - 1] = invfact[i] * i % MOD;

    auto C = [&](int n, int k) -> long long {
        if (k < 0 || k > n) return 0;
        return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD;
    };

    // dp[j] = after processing some heights, number of ways such that
    // exactly j unmatched people remain.
    vector<long long> dp(M + 1, 0), ndp(M + 1, 0);
    dp[0] = 1;
    int processed = 0;

    for (int v = 1; v <= mx; ++v) {
        int c = cnt[v];
        if (c == 0) continue;

        fill(ndp.begin(), ndp.end(), 0);

        // Suppose before processing this height we have j unmatched people
        // from smaller heights.
        // Let x = number of current-height people matched with those j people.
        // Then:
        //   0 <= x <= min(j, c)
        // Remaining c - x people of current height must stay unmatched,
        // because they cannot pair among themselves.
        // New unmatched count = j + c - 2x.
        //
        // Number of ways:
        // choose x among j old unmatched: C(j, x)
        // choose x among c current people: C(c, x)
        // bijection between them: x!
        // total = C(j, x) * C(c, x) * x!
        //       = C(j, x) * c! / (c-x)!
        for (int j = 0; j <= processed; ++j) {
            if (dp[j] == 0) continue;
            int lim = min(j, c);
            for (int x = 0; x <= lim; ++x) {
                int nj = j + c - 2 * x;
                long long ways = C(j, x) * fact[c] % MOD * invfact[c - x] % MOD;
                ndp[nj] = (ndp[nj] + dp[j] * ways) % MOD;
            }
        }

        dp.swap(ndp);
        processed += c;
    }

    cout << dp[0] % MOD << '\n';
    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        int size = 2 * N;
        int[] h = new int[size];
        for (int i = 0; i < size; i++) {
            h[i] = Integer.parseInt(br.readLine());
        }

        // Count frequencies
        int maxH = 100000;
        int[] freq = new int[maxH + 1];
        for (int val : h) freq[val]++;

        // Check impossible
        for (int f : freq) {
            if (f > N) {
                System.out.println(0);
                return;
            }
        }

        // Precompute factorials and inverse factorials
        long[] fact = new long[size + 1];
        long[] invFact = new long[size + 1];
        fact[0] = 1;
        for (int i = 1; i <= size; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[size] = modPow(fact[size], MOD - 2);
        for (int i = size; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long[] dp = new long[N + 1];
        dp[0] = 1;
        int processed = 0;

        for (int val = 1; val <= maxH; val++) {
            int f = freq[val];
            if (f == 0) continue;

            long[] ndp = new long[N + 1];
            for (int open = 0; open <= N; open++) {
                if (dp[open] == 0) continue;
                // We have open unmatched from previous heights
                // and f new people of current height.
                // We can pair k of the f with open people (k <= min(open, f))
                // The rest (f - k) must be kept open for future heights.
                for (int k = 0; k <= Math.min(open, f); k++) {
                    int newOpen = open - k + (f - k);
                    if (newOpen > N) continue;
                    long ways = dp[open] * comb(f, k, fact, invFact) % MOD;
                    ways = ways * fact[open] % MOD;
                    ways = ways * invFact[open - k] % MOD;
                    ndp[newOpen] = (ndp[newOpen] + ways) % MOD;
                }
            }
            dp = ndp;
            processed += f;
        }

        System.out.println(dp[0]);
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    static long comb(int n, int k, long[] fact, long[] invFact) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }
}

import java.util.*;
