public class Main {
    static final long MOD = 998244353;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int i = 0; i < 2 * N; i++) {
            int h = Integer.parseInt(br.readLine().trim());
            cnt.merge(h, 1, Integer::sum);
        }

        // Precompute double factorials: df[k] = (2k-1)!! = 1*3*5*...*(2k-1), df[0]=1
        long[] df = new long[N + 1];
        df[0] = 1;
        for (int k = 1; k <= N; k++) {
            df[k] = df[k-1] * (2*k-1) % MOD;
        }

        // Start with polynomial [1]
        long[] poly = new long[]{1};

        for (int c : cnt.values()) {
            int maxK = c / 2;
            long[] fp = new long[maxK + 1];
            // C(c, 2k) * (2k-1)!! * (-1)^k
            long binom = 1; // C(c,0)
            for (int k = 0; k <= maxK; k++) {
                fp[k] = binom % MOD * df[k] % MOD;
                if (k % 2 == 1) fp[k] = (MOD - fp[k]) % MOD;
                // Update binom: C(c, 2(k+1)) = C(c,2k) * (c-2k)*(c-2k-1) / ((2k+1)*(2k+2))
                if (k < maxK) {
                    binom = binom * ((c - 2*k) % MOD) % MOD * ((c - 2*k - 1) % MOD) % MOD;
                    binom = binom % MOD * modInv((2*k+1)*(long)(2*k+2) % MOD, MOD) % MOD;
                }
            }
            // Convolve poly with fp
            long[] newPoly = new long[poly.length + maxK];
            for (int i = 0; i < poly.length; i++)
                for (int j = 0; j <= maxK; j++)
                    newPoly[i+j] = (newPoly[i+j] + poly[i] * fp[j]) % MOD;
            poly = newPoly;
        }

        long ans = 0;
        for (int m = 0; m < poly.length; m++) {
            int rem = N - m;
            if (rem < 0) break;
            ans = (ans + poly[m] * df[rem]) % MOD;
        }
        System.out.println(ans);
    }

    static long modInv(long a, long mod) {
        return modPow(a, mod - 2, mod);
    }
    static long modPow(long base, long exp, long mod) {
        long result = 1; base %= mod;
        while (exp > 0) { if ((exp&1)==1) result=result*base%mod; base=base*base%mod; exp>>=1; }
        return result;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = 2 * N;

        HashMap<Integer, Integer> freq = new HashMap<>();
        for (int i = 0; i < M; i++) {
            int h = fs.nextInt();
            freq.put(h, freq.getOrDefault(h, 0) + 1);
        }

        int[] cnt = new int[freq.size()];
        int idx = 0;
        for (int v : freq.values()) cnt[idx++] = v;
        Arrays.sort(cnt);

        long[] fact = new long[M + 1];
        long[] invFact = new long[M + 1];
        fact[0] = 1;
        for (int i = 1; i <= M; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[M] = modPow(fact[M], MOD - 2);
        for (int i = M; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        // dp[s] = sum of weights after processing some groups,
        // where s = number of pairs already formed.
        long[] dp = new long[N + 1];
        dp[0] = 1;
        int processed = 0;

        for (int c : cnt) {
            long[] ndp = new long[N + 1];

            // Choose x people from this group to be in the "left" part of a bipartite split
            // and c-x in the "right" part. Valid pairings are between left and right only.
            // Summing over all x with sign gives inclusion-exclusion.
            for (int x = 0; x <= c; x++) {
                int y = c - x;
                int addPairs = x;
                long waysChoose = fact[c] * invFact[x] % MOD * invFact[y] % MOD;
                long sign = ((y & 1) == 0) ? 1 : (MOD - 1);
                long coef = waysChoose * sign % MOD;

                for (int s = 0; s + addPairs <= N; s++) {
                    // Existing processed people count = processed
                    // After adding x left-side vertices from this color,
                    // they must be matched with x right-side vertices among all available.
                    long ways = dp[s] * coef % MOD;
                    ways = ways * fact[s + addPairs] % MOD * invFact[s] % MOD;
                    ndp[s + addPairs] += ways;
                    if (ndp[s + addPairs] >= MOD) ndp[s + addPairs] -= MOD;
                }
            }

            dp = ndp;
            processed += c;
        }

        System.out.println(dp[N] % MOD);
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) != 0) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
